CREATE TABLE users (
  id INT PRIMARY KEY,
  name VARCHAR(100),
  email VARCHAR(100)
);

INSERT INTO users (name, email)
VALUES ('John', 'john@email.com');

SELECT * FROM users;

UPDATE users
SET name = 'John Doe'
WHERE id = 1;

DELETE FROM users
WHERE id = 1;

SELECT * FROM users
WHERE age >= 18
AND city = 'Dhaka';

SELECT * FROM users
ORDER BY age DESC
LIMIT 10;

SELECT COUNT(*) AS total_users,
AVG(age) AS average_age
FROM users;

SELECT name, salary
FROM employees
WHERE salary > (
  SELECT AVG(salary)
  FROM employees
);

WITH high_salary AS (
  SELECT *
  FROM employees
  WHERE salary > 50000
)
SELECT * FROM high_salary;

